#!/usr/bin/env python3
"""
sortnet_recheck v1.0 — agent-0185

Mechanically re-verifies EVERY sorting-network certificate stored anywhere in commons/.

What it checks, using nothing but the published artifact itself (no literature, no trust):
  A. STRUCTURE   : comparators well-formed, indices in range, i!=j.
  B. SORTEDNESS  : 0/1 principle — apply the network to all 2^n binary vectors.
                   (Knuth: a comparator network sorts all inputs iff it sorts all 0/1 inputs.)
  C. SELF-CONSISTENCY: does the file's own claimed comparator count / depth / n match what
                   the published layers actually contain? Depth is recomputed greedily from
                   the comparator sequence (minimum number of parallel layers), and also
                   compared with the file's own layering.

Usage:  python3 agent-0185_sortnet_recheck_v1.0.py [commons_dir] [--json out.json]

Output: one line per certificate + a summary. Exit code 1 if any certificate fails A or B.
"""
import json, os, sys, itertools

def load_json(path):
    try:
        with open(path, errors="replace") as f:
            return json.load(f)
    except Exception:
        return None

def is_pair(x):
    return (isinstance(x, (list, tuple)) and len(x) == 2
            and all(isinstance(v, int) for v in x))

def harvest(obj, path=("$",)):
    """Yield (jsonpath, kind, data) for anything that looks like a network:
       kind 'layers'  -> list of list of pairs
       kind 'flat'    -> list of pairs
    """
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from harvest(v, path + (str(k),))
    elif isinstance(obj, list):
        if obj and all(is_pair(x) for x in obj):
            yield (".".join(path), "flat", obj)
            return
        if obj and all(isinstance(x, list) and x and all(is_pair(p) for p in x) for x in obj):
            yield (".".join(path), "layers", obj)
            return
        for i, v in enumerate(obj):
            yield from harvest(v, path + (f"[{i}]",))

def flatten(kind, data):
    return list(data) if kind == "flat" else [p for layer in data for p in layer]

def greedy_depth(comps, n):
    ready = [0] * n
    for i, j in comps:
        t = max(ready[i], ready[j]) + 1
        ready[i] = ready[j] = t
    return max(ready) if comps else 0

def sorts_all(comps, n):
    """0/1 principle, bit-parallel over all 2^n vectors at once."""
    # channel c holds a bitmask over the 2^n input vectors
    full = (1 << (1 << n)) - 1
    chan = []
    for c in range(n):
        # bit v of chan[c] = bit c of vector v
        m = 0
        for v in range(1 << n):
            if (v >> c) & 1:
                m |= 1 << v
        chan.append(m)
    for i, j in comps:
        a, b = chan[i], chan[j]
        chan[i], chan[j] = a & b, a | b     # min to i, max to j
    # sorted means chan[0] <= chan[1] <= ... i.e. chan[k] subset of chan[k+1]
    for k in range(n - 1):
        if chan[k] & ~chan[k + 1] & full:
            return False, k
    return True, None

def claimed_ints(obj):
    """Pull any self-declared n / size / depth from a dict-ish record."""
    out = {}
    def walk(o):
        if isinstance(o, dict):
            for k, v in o.items():
                kl = str(k).lower()
                if isinstance(v, int):
                    if kl in ("n", "channels", "inputs", "width"):
                        out.setdefault("n", v)
                    if kl in ("comparators", "size", "num_comparators", "comparator_count", "length"):
                        out.setdefault("size", v)
                    if kl in ("depth", "layers_count", "num_layers"):
                        out.setdefault("depth", v)
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    walk(obj)
    return out

def main():
    root = "commons"
    args = [a for a in sys.argv[1:]]
    outp = None
    if "--json" in args:
        k = args.index("--json"); outp = args[k+1]; del args[k:k+2]
    if args:
        root = args[0]

    results = []
    for dirpath, _, files in os.walk(root):
        if "__pycache__" in dirpath:
            continue
        for fn in files:
            if not fn.endswith(".json") and not fn.endswith(".jsonl"):
                continue
            p = os.path.join(dirpath, fn)
            docs = []
            if fn.endswith(".jsonl"):
                for line in open(p, errors="replace"):
                    line = line.strip()
                    if line.startswith("{"):
                        try: docs.append(json.loads(line))
                        except Exception: pass
            else:
                d = load_json(p)
                if d is not None: docs.append(d)
            for di, doc in enumerate(docs):
                cl = claimed_ints(doc) if isinstance(doc, (dict, list)) else {}
                for jp, kind, data in harvest(doc):
                    comps = flatten(kind, data)
                    if len(comps) < 3:
                        continue
                    mx = max(max(a, b) for a, b in comps)
                    mn = min(min(a, b) for a, b in comps)
                    if mn < 0 or mx > 23:
                        continue
                    n = cl.get("n") if cl.get("n", 0) > mx else mx + 1
                    if n > 20:            # 2^n verification budget
                        continue
                    bad = [c for c in comps if c[0] == c[1] or min(c) < 0 or max(c) >= n]
                    ok, witness = (False, None) if bad else sorts_all(comps, n)
                    rec = dict(file=os.path.relpath(p, root), doc=di, jsonpath=jp, kind=kind,
                               n=n, size=len(comps),
                               depth_recomputed=greedy_depth(comps, n),
                               depth_as_published=(len(data) if kind == "layers" else None),
                               structure_ok=not bad, sorts=bool(ok),
                               claimed=cl)
                    results.append(rec)

    # dedupe identical (file, jsonpath)
    seen, uniq = set(), []
    for r in results:
        k = (r["file"], r["doc"], r["jsonpath"])
        if k in seen: continue
        seen.add(k); uniq.append(r)

    fails = [r for r in uniq if not (r["structure_ok"] and r["sorts"])]
    for r in uniq:
        flag = "PASS" if r["sorts"] and r["structure_ok"] else "FAIL"
        mism = []
        c = r["claimed"]
        if "size" in c and c["size"] != r["size"]: mism.append(f"size claimed {c['size']} actual {r['size']}")
        if "depth" in c and c["depth"] != r["depth_recomputed"]: mism.append(f"depth claimed {c['depth']} recomputed {r['depth_recomputed']}")
        print(f"{flag} n={r['n']:2d} size={r['size']:3d} depth={r['depth_recomputed']:2d} "
              f"{r['file']}::{r['jsonpath']}" + ("  [" + "; ".join(mism) + "]" if mism else ""))
    print(f"\n{len(uniq)} networks re-verified · {len(uniq)-len(fails)} sort correctly · {len(fails)} fail")
    if outp:
        json.dump(uniq, open(outp, "w"), indent=1)
    return 1 if fails else 0

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
sortnet_recheck v1.1 — agent-0185   (v1.0 was correct but too slow: O(2^n) mask build)

Mechanically re-verifies EVERY sorting-network certificate stored anywhere in commons/,
using nothing but the published artifact (no literature, no trust in any author).

CHECKS
  A. STRUCTURE       comparators well-formed; indices in range; i != j.
  B. SORTEDNESS      0/1 principle (Knuth): a comparator network sorts every input iff it
                     sorts all 2^n binary inputs. Verified bit-parallel: channel c is one
                     big integer whose bit v is bit c of input vector v, so ALL 2^n inputs
                     are pushed through the network simultaneously with n AND/OR ops per
                     comparator. Masks are built by pattern-doubling, not by a 2^n loop.
  C. SELF-CONSISTENCY does the file's OWN claimed n / comparator-count / depth agree with
                     the layers it publishes? Depth is recomputed greedily (the minimum
                     number of parallel layers of the given comparator sequence).

No literature table is used anywhere: every verdict here is checkable on this machine.

Usage: python3 agent-0185_sortnet_recheck_v1.1_*.py [commons_dir] [--json out] [--maxn 16]
Exit 1 if any harvested network fails A or B.
"""
import json, os, sys

MAXN_DEFAULT = 16

def chan_masks(n):
    """masks[c]: bit v set iff bit c of v is 1, for v in [0, 2^n)."""
    N = 1 << n
    masks = []
    for c in range(n):
        half = 1 << c
        block = ((1 << half) - 1) << half      # one period: 2^c zeros then 2^c ones
        period = half << 1
        m = block
        while period < N:
            m |= m << period
            period <<= 1
        masks.append(m & ((1 << N) - 1))
    return masks

def sorts_all(comps, n):
    chan = chan_masks(n)
    for i, j in comps:
        a, b = chan[i], chan[j]
        if a != b:
            chan[i], chan[j] = a & b, a | b    # min -> lower index, max -> higher
    for k in range(n - 1):
        if chan[k] & ~chan[k + 1]:
            return False
    return True

def greedy_depth(comps, n):
    ready = [0] * n
    for i, j in comps:
        t = max(ready[i], ready[j]) + 1
        ready[i] = ready[j] = t
    return max(ready) if comps else 0

def is_pair(x):
    return isinstance(x, (list, tuple)) and len(x) == 2 and all(isinstance(v, int) for v in x)

def harvest(obj, path=("$",)):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from harvest(v, path + (str(k),))
    elif isinstance(obj, list):
        if obj and all(is_pair(x) for x in obj):
            yield (".".join(path), "flat", obj); return
        if obj and all(isinstance(x, list) and x and all(is_pair(p) for p in x) for x in obj):
            yield (".".join(path), "layers", obj); return
        for i, v in enumerate(obj):
            yield from harvest(v, path + (f"[{i}]",))

def claimed_ints(obj):
    out = {}
    def walk(o):
        if isinstance(o, dict):
            for k, v in o.items():
                kl = str(k).lower()
                if isinstance(v, int):
                    if kl in ("n", "channels", "inputs", "width"): out.setdefault("n", v)
                    if kl in ("comparators", "size", "num_comparators", "comparator_count"):
                        out.setdefault("size", v)
                    if kl in ("depth", "num_layers", "layers_count"): out.setdefault("depth", v)
                walk(v)
        elif isinstance(o, list):
            for v in o: walk(v)
    walk(obj)
    return out

HINTS = ('"layers"', "comparator", "sortnet", "sorting_network", "network")

def main():
    args = sys.argv[1:]
    outp = None; maxn = MAXN_DEFAULT
    for flag, cast in (("--json", str), ("--maxn", int)):
        if flag in args:
            k = args.index(flag); val = cast(args[k+1]); del args[k:k+2]
            if flag == "--json": outp = val
            else: maxn = val
    root = args[0] if args else "commons"

    uniq, seen = [], set()
    for dirpath, _, files in os.walk(root):
        if "__pycache__" in dirpath: continue
        for fn in sorted(files):
            if not (fn.endswith(".json") or fn.endswith(".jsonl")): continue
            p = os.path.join(dirpath, fn)
            try:
                raw = open(p, errors="replace").read()
            except Exception:
                continue
            if not any(h in raw for h in HINTS): continue
            docs = []
            if fn.endswith(".jsonl"):
                for line in raw.splitlines():
                    line = line.strip()
                    if line.startswith("{"):
                        try: docs.append(json.loads(line))
                        except Exception: pass
            else:
                try: docs.append(json.loads(raw))
                except Exception: continue
            for di, doc in enumerate(docs):
                cl = claimed_ints(doc)
                for jp, kind, data in harvest(doc):
                    comps = [tuple(c) for c in (data if kind == "flat"
                                                else [q for L in data for q in L])]
                    if len(comps) < 3: continue
                    lo = min(min(c) for c in comps); hi = max(max(c) for c in comps)
                    if lo < 0 or hi >= maxn: continue
                    n = cl["n"] if cl.get("n", 0) > hi else hi + 1
                    if n > maxn: continue
                    key = (os.path.relpath(p, root), di, jp)
                    if key in seen: continue
                    seen.add(key)
                    bad = [c for c in comps if c[0] == c[1] or min(c) < 0 or max(c) >= n]
                    ok = False if bad else sorts_all(comps, n)
                    uniq.append(dict(file=key[0], doc=di, jsonpath=jp, kind=kind, n=n,
                                     size=len(comps), depth_recomputed=greedy_depth(comps, n),
                                     depth_as_published=(len(data) if kind == "layers" else None),
                                     structure_ok=not bad, sorts=bool(ok), claimed=cl))
    fails = [r for r in uniq if not (r["structure_ok"] and r["sorts"])]
    mismatched = []
    for r in sorted(uniq, key=lambda r: (r["n"], r["size"], r["file"])):
        c = r["claimed"]; mism = []
        if "size" in c and c["size"] != r["size"]:
            mism.append(f"size claimed {c['size']} != actual {r['size']}")
        if "depth" in c and c["depth"] != r["depth_recomputed"]:
            mism.append(f"depth claimed {c['depth']} != recomputed {r['depth_recomputed']}")
        if mism: mismatched.append((r, mism))
        print(f"{'PASS' if r['sorts'] and r['structure_ok'] else 'FAIL'} "
              f"n={r['n']:2d} size={r['size']:3d} depth={r['depth_recomputed']:2d} "
              f"{r['file']}::{r['jsonpath']}" + ("  [" + "; ".join(mism) + "]" if mism else ""))
    print(f"\n{len(uniq)} networks harvested · {len(uniq)-len(fails)} sort all 2^n inputs · "
          f"{len(fails)} fail · {len(mismatched)} self-inconsistent counts")
    if outp: json.dump(uniq, open(outp, "w"), indent=1)
    return 1 if fails else 0

if __name__ == "__main__":
    sys.exit(main())

