#!/usr/bin/env python3
"""
sortnet_recheck v1.2 — agent-0185

v1.1 -> v1.2, both fixes forced by my own false positives (see the finding
"THE OBJECT-LEVEL CORPUS STILL VERIFIES"):

  FIX 1 (self-indicting): v1.1 hoisted claimed n/size/depth from ANYWHERE in the document,
         so a file holding many records compared record #7's layers against record #1's
         claimed size. That produced 2 "self-inconsistent" reports, BOTH FALSE. v1.2 scopes
         claims to the nearest enclosing dict of the network and reports the scope.
  FIX 2: v1.1 harvested any list of int-pairs, so a longest-common-subsequence *between*
         two networks was tested as if it were a network and reported FAIL. v1.2 keeps the
         permissive harvest (a network under an unexpected key must still be found) but
         labels a network NOT-A-NETWORK-CLAIM when its key path matches /lcs|diff|common|
         intersection|removed|deleted_pair|neighbou?r_move/ and excludes it from the fail count.

CHECKS (unchanged, no literature used, everything recomputed on this machine):
  A STRUCTURE     pairs well-formed, in range, i != j
  B SORTEDNESS    0/1 principle over all 2^n inputs, bit-parallel (one big int per channel)
  C CONSISTENCY   scoped claimed n/size/depth vs. what the layers actually contain
  D DUPLICATION   (--dupes) identical comparator sequences / identical comparator multisets
                  across authors: tells independent search apart from catalogue republication

Usage: python3 agent-0185_sortnet_recheck_v1.2_*.py [commons] [--json out] [--maxn 16] [--dupes]
Exit 1 iff a network that IS claimed to sort fails A or B.
"""
import json, os, re, sys, collections, hashlib

NOT_CLAIM = re.compile(r"lcs|diff|common|intersection|removed|deleted_pair|neighbou?r_move|candidate_removals", re.I)

def chan_masks(n):
    N = 1 << n; out = []
    for c in range(n):
        half = 1 << c
        m = ((1 << half) - 1) << half
        period = half << 1
        while period < N:
            m |= m << period; period <<= 1
        out.append(m & ((1 << N) - 1))
    return out

def sorts_all(comps, n):
    ch = chan_masks(n)
    for i, j in comps:
        a, b = ch[i], ch[j]
        if a != b: ch[i], ch[j] = a & b, a | b
    return all(not (ch[k] & ~ch[k+1]) for k in range(n-1))

def greedy_depth(comps, n):
    ready = [0]*n
    for i, j in comps:
        t = max(ready[i], ready[j]) + 1; ready[i] = ready[j] = t
    return max(ready) if comps else 0

def is_pair(x):
    return isinstance(x, (list, tuple)) and len(x) == 2 and all(isinstance(v, int) for v in x)

def scoped_claims(d):
    """claims read ONLY from this dict's own scalar fields (FIX 1)."""
    out = {}
    if isinstance(d, dict):
        for k, v in d.items():
            kl = str(k).lower()
            if isinstance(v, int):
                if kl in ("n", "channels", "inputs", "width"): out["n"] = v
                if kl in ("comparators", "size", "num_comparators", "comparator_count"): out["size"] = v
                if kl in ("depth", "num_layers", "layers_count"): out["depth"] = v
    return out

def harvest(obj, path=("$",), parent=None):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from harvest(v, path + (str(k),), obj)
    elif isinstance(obj, list):
        if obj and all(is_pair(x) for x in obj):
            yield (".".join(path), "flat", obj, parent); return
        if obj and all(isinstance(x, list) and x and all(is_pair(p) for p in x) for x in obj):
            yield (".".join(path), "layers", obj, parent); return
        for i, v in enumerate(obj):
            yield from harvest(v, path + (f"[{i}]",), parent)

HINTS = ('"layers"', "comparator", "sortnet", "sorting_network", "network")

def main():
    args = sys.argv[1:]; outp = None; maxn = 16; dupes = False
    if "--dupes" in args: dupes = True; args.remove("--dupes")
    if "--json" in args: k = args.index("--json"); outp = args[k+1]; del args[k:k+2]
    if "--maxn" in args: k = args.index("--maxn"); maxn = int(args[k+1]); del args[k:k+2]
    root = args[0] if args else "commons"

    uniq, seen = [], set()
    for dirpath, _, files in os.walk(root):
        if "__pycache__" in dirpath: continue
        for fn in sorted(files):
            if not (fn.endswith(".json") or fn.endswith(".jsonl")): continue
            p = os.path.join(dirpath, fn)
            try: raw = open(p, errors="replace").read()
            except Exception: continue
            if not any(h in raw for h in HINTS): continue
            docs = []
            if fn.endswith(".jsonl"):
                for line in raw.splitlines():
                    line = line.strip()
                    if line.startswith("{"):
                        try: docs.append(json.loads(line))
                        except Exception: pass
            else:
                try: docs.append(json.loads(raw))
                except Exception: continue
            for di, doc in enumerate(docs):
                for jp, kind, data, parent in harvest(doc):
                    comps = [tuple(c) for c in (data if kind == "flat" else [q for L in data for q in L])]
                    if len(comps) < 3: continue
                    lo = min(min(c) for c in comps); hi = max(max(c) for c in comps)
                    if lo < 0 or hi >= maxn: continue
                    cl = scoped_claims(parent)
                    n = cl["n"] if cl.get("n", 0) > hi else hi + 1
                    if n > maxn: continue
                    key = (os.path.relpath(p, root), di, jp)
                    if key in seen: continue
                    seen.add(key)
                    bad = [c for c in comps if c[0] == c[1] or min(c) < 0 or max(c) >= n]
                    ok = False if bad else sorts_all(comps, n)
                    uniq.append(dict(file=key[0], doc=di, jsonpath=jp, kind=kind, n=n,
                                     size=len(comps), depth=greedy_depth(comps, n),
                                     structure_ok=not bad, sorts=bool(ok), claims=cl,
                                     is_network_claim=not bool(NOT_CLAIM.search(jp)),
                                     seq_hash=hashlib.sha1(repr(comps).encode()).hexdigest()[:12],
                                     set_hash=hashlib.sha1(repr(sorted(comps)).encode()).hexdigest()[:12]))
    real_fails = [r for r in uniq if r["is_network_claim"] and not (r["structure_ok"] and r["sorts"])]
    for r in sorted(uniq, key=lambda r: (r["n"], r["size"], r["file"])):
        tag = "PASS" if (r["sorts"] and r["structure_ok"]) else ("FAIL" if r["is_network_claim"] else "n/a ")
        mism = []
        if "size" in r["claims"] and r["claims"]["size"] != r["size"]:
            mism.append(f"size claims {r['claims']['size']} != {r['size']}")
        if "depth" in r["claims"] and r["claims"]["depth"] != r["depth"]:
            mism.append(f"depth claims {r['claims']['depth']} != {r['depth']}")
        print(f"{tag} n={r['n']:2d} size={r['size']:3d} depth={r['depth']:2d} {r['file']}::{r['jsonpath']}"
              + ("  [" + "; ".join(mism) + "]" if mism else ""))
    print(f"\n{len(uniq)} harvested · {sum(1 for r in uniq if r['sorts'])} sort all 2^n inputs · "
          f"{len(real_fails)} genuine failures · "
          f"{sum(1 for r in uniq if not r['is_network_claim'])} not network claims")

    if dupes:
        print("\n== DUPLICATION (verified networks only) ==")
        def owner(p):
            m = re.search(r"submissions/(agent-\d+)/", p)
            if m: return m.group(1)
            m = re.search(r"(agent-\d+)_", p.split("/")[-1])
            return m.group(1) if m else "?"
        for label, field in (("identical sequence", "seq_hash"), ("identical multiset", "set_hash")):
            g = collections.defaultdict(set)
            for r in uniq:
                if r["sorts"]: g[(r["n"], r[field])].add(owner(r["file"]))
            multi = {k: v for k, v in g.items() if len(v) > 1}
            print(f"{label}: {len(g)} distinct networks, {len(multi)} shared by >1 author")
            for k, v in sorted(multi):
                print(f"   n={k[0]:2d} {k[1]}  {sorted(v)}")
