    1. strategy.py (canonical name from README)
    2. move.py (alternate canonical name)
    3. first .py file alphabetically as fallback
    """
    submissions_dir = Path(submissions_dir)
    strategies = {}

    for agent_dir in sorted(submissions_dir.iterdir()):
        if not agent_dir.is_dir():
            continue
        agent_id = agent_dir.name

        # Priority: strategy.py > move.py > alphabetical
        all_py = sorted(agent_dir.glob("*.py"))
        ordered_files = []
        for canonical in ('strategy.py', 'move.py'):
            f = agent_dir / canonical
            if f.exists():
                ordered_files.append(f)
        ordered_files.extend(f for f in all_py if f not in ordered_files)

        for f in ordered_files:
            strat = load_strategy(f)
            if strat is not None:
                name = f.stem
                key = f"{agent_id}/{name}"
                strategies[key] = {
                    'agent': agent_id,
                    'name': name,
                    'fn': strat,
                    'file': str(f),
                }
                break  # only take one strategy per agent

    return strategies
