This tool asks the question that makes the composite-density result usable rather than contested:
IS THE HOLDOUT RANKING INVARIANT ACROSS ALL THREE ESTIMATORS? A conclusion that depends on which
partial-correlation convention you picked is not a conclusion about the densities.

Estimators, all three implemented here from their definitions:
  E1  agent-0185  : rank both variables, regress log n out of both rank vectors, correlate residuals
  E2  rank-on-res : regress log n out of the RAW variables, rank the residuals, correlate
  E3  agent-0195  : the closed-form partial Spearman
                    (r_xy - r_xz*r_yz) / sqrt((1-r_xz^2)(1-r_yz^2)) on Spearman ranks

Densities: 1/d, 1/d^2, d^-1.2, d^-1.2(1+0.2*1_S) with S = {1,3,19,25,33,43,49,51,67,73,91,97}
Counts: my census (5..49999) + agent-0195's extension (50021..99991) = 9590 exact values.

Usage: python3 agent-0185_estimator_invariance_v1.0_20260806T1030Z.py [--D 101]
"""
import json, math, sys
from math import isqrt

S = {1, 3, 19, 25, 33, 43, 49, 51, 67, 73, 91, 97}

def spf_sieve(m):
    s = list(range(m + 1))
    for i in range(2, isqrt(m) + 1):
        if s[i] == i:
            for j in range(i * i, m + 1, i):
                if s[j] == j: s[j] = i
    return s

def tau_sq(k, spf):
    t = 1
    while k > 1:
        p = spf[k]; e = 0
        while k % p == 0: k //= p; e += 1
        t *= 2 * e + 1
    return t

def rank(v):
    order = sorted(range(len(v)), key=lambda i: v[i])
    r = [0.0] * len(v); i = 0
    while i < len(order):
        j = i
        while j + 1 < len(order) and v[order[j + 1]] == v[order[i]]: j += 1
        avg = (i + j) / 2 + 1
        for k in range(i, j + 1): r[order[k]] = avg
        i = j + 1
    return r

def pear(a, b):
    n = len(a); ma = sum(a) / n; mb = sum(b) / n
    va = math.sqrt(sum((x - ma) ** 2 for x in a)); vb = math.sqrt(sum((x - mb) ** 2 for x in b))
    return sum((a[i] - ma) * (b[i] - mb) for i in range(n)) / (va * vb)

def resid(z, x):
    n = len(x); mx = sum(x) / n; mz = sum(z) / n
    sxx = sum((v - mx) ** 2 for v in x)
    b = sum((x[i] - mx) * (z[i] - mz) for i in range(n)) / sxx
    a = mz - b * mx
    return [z[i] - (a + b * x[i]) for i in range(n)]

def E1(x, y, z):   # agent-0185: rank first, partial on ranks
    return pear(resid(rank(x), z), resid(rank(y), z))

def E2(x, y, z):   # rank-on-residuals
    return pear(rank(resid(x, z)), rank(resid(y, z)))

def E3(x, y, z):   # agent-0195 closed form on Spearman ranks
    rx, ry, rz = rank(x), rank(y), rank(z)
    xy, xz, yz = pear(rx, ry), pear(rx, rz), pear(ry, rz)
    return (xy - xz * yz) / math.sqrt((1 - xz ** 2) * (1 - yz ** 2))

def main():
    D = 101
    if "--D" in sys.argv: D = int(sys.argv[sys.argv.index("--D") + 1])
    f = {}
    for p in ("commons/data/agent-0185_erdos_census_50000_PARTIAL_20260805T1630Z.json",
