            for r in rows:
                n = r.get("n"); v = r.get("representations", r.get("reps"))
                if isinstance(n, int) and isinstance(v, int) and n > 3: f.setdefault(n, v)
        except Exception as e: print("skip", p, e)
    spf = spf_sieve(max(f) // 4 + D + 10)
    cache = {}
    def sc(n, rho):
        s = 0.0
        for d in range(1, D + 1):
            if (n + d) % 4: continue
            m = (n + d) // 4
            if m < 1: continue
            t = cache.get(m)
            if t is None: t = cache[m] = tau_sq(m, spf)
            s += t * rho(d)
        return s
    RHO = [("1/d", lambda d: 1.0 / d),
           ("1/d^2", lambda d: 1.0 / d ** 2),
           ("d^-1.2", lambda d: d ** -1.2),
           ("d^-1.2(1+.2*1S)", lambda d: (d ** -1.2) * (1.2 if d in S else 1.0))]
    print(f"{len(f)} exact counts · D={D} · three estimators\n")
    for gl, ns in (("IN-SAMPLE n<=25000", sorted(n for n in f if n <= 25000)),
                   ("HOLDOUT 25000<n<=100000", sorted(n for n in f if n > 25000))):
        z = [math.log(n) for n in ns]
        y = [math.log(f[n]) for n in ns]
        print(f"{gl}  ({len(ns)} primes)")
        print(f"   {'density':18s} {'E1 (mine)':>10s} {'E2 rank-res':>12s} {'E3 (0195)':>10s}")
        res = {}
        for lab, rho in RHO:
            x = [sc(n, rho) for n in ns]
            res[lab] = (E1(x, y, z), E2(x, y, z), E3(x, y, z))
            print(f"   {lab:18s} {res[lab][0]:10.4f} {res[lab][1]:12.4f} {res[lab][2]:10.4f}")
        names = [l for l, _ in RHO]
        for i, en in enumerate(("E1", "E2", "E3")):
            order = sorted(names, key=lambda l: -res[l][i])
            print(f"   ranking by {en}: {' > '.join(order)}")
        agree = len({tuple(sorted(names, key=lambda l: -res[l][i])) for i in range(3)}) == 1
        print(f"   ALL THREE ESTIMATORS AGREE ON THE RANKING: {agree}\n")

if __name__ == "__main__":
    sys.exit(main())

